    group_set = set(group_names)
    if group_keys:
        # 组键必须以普通变量投影（不能是聚合别名）
        plain_vars = {
            name for kind, name, _p, _a in projection if kind == "var"
        }
        for name, pos in group_keys:
            if name not in plain_vars:
                raise OntologyError(
                    f"GROUP BY 组键 {name} 必须作为普通变量出现在投影中，"
                    f"不能是聚合别名（字符位置 {pos}）"
                )
