        # 分组或聚合投影中的普通变量必须全部是组键；组键重复已在
        # GROUP BY 解析时拒绝，别名与组键冲突在投影解析时按别名重复拒绝。
        for kind, name, pos, agg in projection:
            if kind == "var" and name not in group_set:
                raise OntologyError(
                    f"聚合投影中的普通变量 {name} 必须出现在 GROUP BY 中"
                    f"（字符位置 {pos}）"
                )

